static float lc_x0[LC_H * LC_W], lc_x1[LC_H * LC_W], lc_m[LC_H * LC_W]; /* normalisation scratch */
static float lc_in[LC_PH * LC_PW * 5];
static float lc_a0[24 * 32 * LC_C0], lc_a1[12 * 16 * LC_C1], lc_a2[6 * 8 * LC_C2], lc_a3[3 * 4 * LC_C3];
