                    const uint8_t *base = I + (cv + dy - r) * w + cu + dx - r;
                    v128_t st = wasm_i32x4_splat(0), sq = st, sq2 = st;
                    for (int j = 0; j < MAP_PS; j++, base += w) {
                        v128_t rw = wasm_v128_load(base), lo = wasm_u16x8_extend_low_u8x16(rw), hi = wasm_v128_and(wasm_u16x8_extend_high_u8x16(rw), mask3);
                        st = wasm_i32x4_add(st, wasm_i32x4_add(wasm_i32x4_dot_i16x8(tl[j], lo), wasm_i32x4_dot_i16x8(th[j], hi)));
                        sq = wasm_i32x4_add(sq, wasm_i32x4_dot_i16x8(wasm_i16x8_add(lo, hi), ones));
                        sq2 = wasm_i32x4_add(sq2, wasm_i32x4_add(wasm_i32x4_dot_i16x8(lo, lo), wasm_i32x4_dot_i16x8(hi, hi)));
                    }
