/* Shi-Tomasi: smaller eigenvalue of the 3x3 sum of gradient outer products (central differences) */
static double corner_score(const uint8_t *I, int x, int y) {
    double sxx = 0, syy = 0, sxy = 0;
    for (int v = -1; v <= 1; v++)
        for (int u = -1; u <= 1; u++) {
            const uint8_t *p = I + (y + v) * IMG_W + x + u;
            int gx = p[1] - p[-1], gy = p[IMG_W] - p[-IMG_W];
            sxx += gx * gx; syy += gy * gy; sxy += gx * gy;
        }
    return 0.5 * (sxx + syy) - sqrt(0.25 * (sxx - syy) * (sxx - syy) + sxy * sxy);
}

static int cell_of(double x, double y) {
    int gx = (int)(x / CELL_W), gy = (int)(y / CELL_H);
    if (gx < 0) gx = 0;
    if (gx >= GRID_X) gx = GRID_X - 1;
    if (gy < 0) gy = 0;
    if (gy >= GRID_Y) gy = GRID_Y - 1;
    return gy * GRID_X + gx;
}

/* top up the grid: in every cell without a live track, the best corner (stride 2) above DETECT_MIN_SCORE becomes a new
   track. Only empty cells are scored, so the cost follows the number of lost tracks. */
#ifndef DET_PERIOD
#define DET_PERIOD 1
#endif
#ifndef VIS4
#define VIS4 0   /* approx arm: vision sliced over the clone cycle: pyramid + clone on phase 0 only, tracks tracked 1/4 per frame (5 Hz) on the stored image pair */
#endif
static int vis_cycle, det_k = -1;
#ifndef DET_BUDGET
#define DET_BUDGET 1000  /* tier1m: max empty cells scored per frame (round robin) */
#endif
#ifndef DET_T0
#define DET_T0 0         /* tier1m: frames with budget DET_BUDGET0 */
#endif
#ifndef DET_BUDGET0
#define DET_BUDGET0 1000
#endif
#ifndef DET_STRIDE
#define DET_STRIDE 2     /* candidate stride inside a cell (2 = B16) */
#endif
#ifndef DET_COOL
#define DET_COOL 0       /* tier1m: frames before a cell that yielded no corner is rescored */
#endif
